  if (!c) return undefined;
  if (BRANDS[c]) return BRANDS[c];
  if (GENERICS.has(c)) return c;
  const words = c.split(" ");
  for (const n of [2, 1]) {
    if (words.length > n) {
      const head = words.slice(0, n).join(" ");
      if (BRANDS[head]) return BRANDS[head];
      if (GENERICS.has(head)) return head;
    }
  }
  return undefined;
